.cpu-load-chart {
    position: relative;
    flex: 1 1 auto;
    min-width: 0;
    min-height: 0;
}

/*
 * Yagr's CSS API (--yagr-* variables) mapped onto Gravity UI semantic tokens,
 * so the canvas follows the active light/dark theme. Two classes beat Yagr's
 * own `.yagr_theme_*` rules.
 */
.cpu-load-chart .cpu-load-chart__plot {
    --yagr-font-family: var(--g-text-body-font-family);
    --yagr-background: var(--g-color-base-background);
    --yagr-grid: var(--g-color-line-generic);
    --yagr-axis-stroke: var(--g-color-text-secondary);
    --yagr-title-color: var(--g-color-text-primary);

    position: absolute;
    inset: 0;
}

.cpu-load-chart__overlay {
    position: absolute;
    inset: 0;
    background: var(--g-color-base-background);
}

.cpu-load-chart__reset {
    position: absolute;
    top: var(--g-spacing-2);
    right: var(--g-spacing-2);
}

/* Tooltip is rendered into document.body; styled through Yagr's `tooltip.className` option. */
.yagr-tooltip.cpu-load-chart__tooltip {
    --yagr-tooltip-font-family: var(--g-text-body-font-family);

    color: var(--g-color-text-primary);
    background-color: var(--g-color-infographics-tooltip-bg);
    border-radius: var(--g-border-radius-m);
    box-shadow: 0 2px 8px var(--g-color-sfx-shadow);
}

